UPDATE app_state SET data=json_set(data,'$.feedbackMessages',json((
 SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')='2c71e0ef-52c2-4cba-91e9-96da2b9080e2' THEN json_patch(value,json_object('status','done','adminComment','Versões 135/136 publicadas: setas Cristal Lunar e Lâmina Solar; nomes Rubi e Gelo Lunar; molduras Órbita Prateada e Quartzo Rosa; Insígnia Cometa; título Guardião Master; poderes Antídoto e Acordo Estelar. Dois baús Master com limites de recompensa/revenda. Brinde Master Aurora entregue uma vez a cada uma das 9 contas aprovadas, com aviso no sino. Sem alterações nas chances dos jogos, saldos ou compras anteriores.','updatedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'completedAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'))) ELSE value END)) FROM json_each(app_state.data,'$.feedbackMessages')
))),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1;
